package com.bank.audit;

import java.util.logging.*;

public class MiddleNodeDemo {
    private static final Logger log = Logger.getLogger(MiddleNodeDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TxnListAuditor auditor = new TxnListAuditor();

        TxnNode head = TxnNode.of("T1", "T2", "T3", "T4", "T5");
        TxnNode mid = auditor.middleTransaction(head);
        log.info(() -> "Middle transaction (odd length 5): " + mid.id);

        TxnNode even = TxnNode.of("T1", "T2", "T3", "T4");
        TxnNode midEven = auditor.middleTransaction(even);
        log.info(() -> "Middle transaction (even length 4): " + midEven.id);
    }
}

